<?php require_once 'config.php';require_admin();$page_title='Data Warga';$page_desc='Tambah, ubah, hapus, dan cari data warga.';
if(isset($_GET['hapus'])){$s=$pdo->prepare('DELETE FROM warga WHERE id=?');$s->execute([(int)$_GET['hapus']]);flash('success','Data warga berhasil dihapus.');header('Location: warga.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$d=[trim($_POST['nik']),trim($_POST['nama']),$_POST['jk'],trim($_POST['ttl']),trim($_POST['alamat']),trim($_POST['pekerjaan']),trim($_POST['kk'])];if($id){$s=$pdo->prepare('UPDATE warga SET nik=?,nama=?,jk=?,ttl=?,alamat=?,pekerjaan=?,kk=? WHERE id=?');$s->execute([...$d,$id]);flash('success','Data warga berhasil diperbarui.');}else{$s=$pdo->prepare('INSERT INTO warga(nik,nama,jk,ttl,alamat,pekerjaan,kk) VALUES(?,?,?,?,?,?,?)');$s->execute($d);flash('success','Data warga berhasil ditambahkan.');}header('Location: warga.php');exit;}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM warga WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$pdo->query('SELECT * FROM warga ORDER BY id DESC')->fetchAll();require 'partials/header.php';
if(isset($_GET['action'])||$edit): ?><section class="panel form-panel"><div class="panel-head"><h3><?=$edit?'Edit':'Tambah'?> Data Warga</h3><a href="warga.php" class="btn light">Kembali</a></div><form method="post" class="form-grid"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div><label>NIK</label><input name="nik" maxlength="16" required value="<?=e($edit['nik']??'')?>"></div><div><label>Nama Lengkap</label><input name="nama" required value="<?=e($edit['nama']??'')?>"></div><div><label>Jenis Kelamin</label><select name="jk"><option value="L" <?=($edit['jk']??'')==='L'?'selected':''?>>Laki-laki</option><option value="P" <?=($edit['jk']??'')==='P'?'selected':''?>>Perempuan</option></select></div><div><label>Tempat, Tanggal Lahir</label><input name="ttl" required value="<?=e($edit['ttl']??'')?>"></div><div><label>Alamat</label><input name="alamat" required value="<?=e($edit['alamat']??'')?>"></div><div><label>Pekerjaan</label><input name="pekerjaan" required value="<?=e($edit['pekerjaan']??'')?>"></div><div><label>Nomor KK</label><input name="kk" maxlength="16" required value="<?=e($edit['kk']??'')?>"></div><div class="form-actions"><button class="btn primary">💾 Simpan Data</button></div></form></section><?php else: ?><section class="panel"><div class="panel-head"><h3>Daftar Warga</h3><a href="warga.php?action=tambah" class="btn primary">+ Tambah Warga</a></div><input class="search" data-table-search="#wargaTable" placeholder="🔎 Cari nama, NIK, alamat..."><div class="table-wrap"><table id="wargaTable"><thead><tr><th>No</th><th>NIK</th><th>Nama</th><th>JK</th><th>Alamat</th><th>Pekerjaan</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $i=>$w): ?><tr><td><?=$i+1?></td><td><?=e($w['nik'])?></td><td><b><?=e($w['nama'])?></b></td><td><?=e($w['jk'])?></td><td><?=e($w['alamat'])?></td><td><?=e($w['pekerjaan'])?></td><td><a class="btn small" href="?edit=<?=$w['id']?>">Edit</a> <a class="btn small danger-btn" data-confirm="Hapus data ini?" href="?hapus=<?=$w['id']?>">Hapus</a></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif;require 'partials/footer.php';
